content:
Looking at this LU decomposition kernel, I need to analyze the loop structure and dependencies carefully before applying optimizations.

The algorithm has:
- An outer loop over `i`
- Two inner loop nests: one for `j < i` (lower triangular update) and one for `j >= i` (upper triangular update)
- Each has a `k` loop doing accumulation with loop-carried dependency on `A[i][j]`

Key observations:
1. The `k` loops have loop-carried dependencies (accumulation into `A[i][j]`)
2. The `j` loops can be pipelined after the `k` loops are handled
3. Array `A` is 2D and needs partitioning for parallel access
4. The innermost `k` loops should be pipelined

```cpp
#include "lu.h"

extern "C" {

void kernel_lu(
               double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Local copy of A for efficient access
    double localA[N][N];
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=1

    // Load A into local buffer
    load_i: for (int i = 0; i < N; i++) {
        load_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localA[i][j] = A[i][j];
        }
    }

    const int n = N;
    int i, j, k;

    for (i = 0; i < n; i++) {
        // Lower triangular: j < i
        for (j = 0; j < i; j++) {
            double sum = localA[i][j];
            for (k = 0; k < j; k++) {
#pragma HLS PIPELINE II=1
                sum -= localA[i][k] * localA[k][j];
            }
            localA[i][j] = sum / localA[j][j];
        }
        // Upper triangular: j >= i
        for (j = i; j < n; j++) {
            double sum = localA[i][j];
            for (k = 0; k < i; k++) {
#pragma HLS PIPELINE II=1
                sum -= localA[i][k] * localA[k][j];
            }
            localA[i][j] = sum;
        }
    }

    // Store result back to global memory
    store_i: for (int i = 0; i < N; i++) {
        store_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = localA[i][j];
        }
    }
}

} // extern "C"
```

Looking at the current code, it already has a local buffer (`localA`) but the compute phase operates directly on this single buffer without true tiling. The LU decomposition has a sequential dependency structure, so I'll apply tiling by processing the matrix in block tiles, using local tile buffers for the panel/block computations to improve data reuse and memory access patterns.

For LU decomposition, a natural tiling approach is to use a **blocked LU** (also called "tiled LU") where we:
1. Process the matrix in `TILE_SIZE × TILE_SIZE` blocks
2. Load diagonal blocks and panel blocks into local tile buffers
3. Compute on local tiles (diagonal factorization, panel updates, trailing matrix updates)

```cpp
#include "lu.h"
#include <string.h>

// Tile size for blocked LU decomposition
#define TILE_SIZE 24  // N=120, 120/24=5 tiles exactly

extern "C" {

// Load a tile from global A into local tile buffer
static void load_tile(double A[N][N], double tile[TILE_SIZE][TILE_SIZE],
                      int row_start, int col_start) {
    load_tile_i: for (int i = 0; i < TILE_SIZE; i++) {
        load_tile_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
            int gi = row_start + i;
            int gj = col_start + j;
            tile[i][j] = (gi < N && gj < N) ? A[gi][gj] : 0.0;
        }
    }
}

// Store a tile from local tile buffer back to global A
static void store_tile(double A[N][N], double tile[TILE_SIZE][TILE_SIZE],
                       int row_start, int col_start) {
    store_tile_i: for (int i = 0; i < TILE_SIZE; i++) {
        store_tile_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
            int gi = row_start + i;
            int gj = col_start + j;
            if (gi < N && gj < N)
                A[gi][gj] = tile[i][j];
        }
    }
}

void kernel_lu(
               double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Full local copy of A for tiled computation
    double localA[N][N];
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2

    // ---- LOAD PHASE: bring all of A into local buffer ----
    load_i: for (int i = 0; i < N; i++) {
        load_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localA[i][j] = A[i][j];
        }
    }

    // ---- COMPUTE PHASE: blocked (tiled) LU decomposition ----
    // Number of tiles along each dimension
    const int NUM_TILES = N / TILE_SIZE;

    // Local tile buffers for the three tile roles in blocked LU
    double diag_tile[TILE_SIZE][TILE_SIZE];    // diagonal (pivot) block
    double col_panel[TILE_SIZE][TILE_SIZE];    // block in pivot column
    double row_panel[TILE_SIZE][TILE_SIZE];    // block in pivot row
    double update_tile[TILE_SIZE][TILE_SIZE];  // trailing submatrix block

#pragma HLS ARRAY_PARTITION variable=diag_tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=col_panel complete dim=2
#pragma HLS ARRAY_PARTITION variable=row_panel complete dim=2
#pragma HLS ARRAY_PARTITION variable=update_tile complete dim=2

    tile_k: for (int tk = 0; tk < NUM_TILES; tk++) {
        int k0 = tk * TILE_SIZE;

        // --- Step 1: Load diagonal tile and compute its LU in-place ---
        load_diag: for (int i = 0; i < TILE_SIZE; i++) {
            for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                diag_tile[i][j] = localA[k0 + i][k0 + j];
            }
        }

        // LU factorize the diagonal tile (unblocked)
        diag_lu_i: for (int i = 0; i < TILE_SIZE; i++) {
            // Lower part of diagonal tile
            diag_lu_lower_j: for (int j = 0; j < i; j++) {
                double sum = diag_tile[i][j];
                diag_lu_lower_k: for (int kk = 0; kk < j; kk++) {
#pragma HLS PIPELINE II=1
                    sum -= diag_tile[i][kk] * diag_tile[kk][j];
                }
                diag_tile[i][j] = sum / diag_tile[j][j];
            }
            // Upper part of diagonal tile
            diag_lu_upper_j: for (int j = i; j < TILE_SIZE; j++) {
                double sum = diag_tile[i][j];
                diag_lu_upper_k: for (int kk = 0; kk < i; kk++) {
#pragma HLS PIPELINE II=1
                    sum -= diag_tile[i][kk] * diag_tile[kk][j];
                }
                diag_tile[i][j] = sum;
            }
        }

        // Write factorized diagonal tile back to localA
        store_diag: for (int i = 0; i < TILE_SIZE; i++) {
            for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                localA[k0 + i][k0 + j] = diag_tile[i][j];
            }
        }

        // --- Step 2: Update column panel (tiles below diagonal) ---
        col_panel_loop: for (int ti = tk + 1; ti < NUM_TILES; ti++) {
            int i0 = ti * TILE_SIZE;

            // Load this column panel tile
            load_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    col_panel[i][j] = localA[i0 + i][k0 + j];
                }
            }

            // Apply L factor from diagonal tile to column panel:
            // col_panel[i][j] -= sum_kk col_panel[i][kk] * diag_tile[kk][j]  for kk < j
            // then col_panel[i][j] /= diag_tile[j][j]
            cpanel_i: for (int i = 0; i < TILE_SIZE; i++) {
                cpanel_j: for (int j = 0; j < TILE_SIZE; j++) {
                    double sum = col_panel[i][j];
                    cpanel_k: for (int kk = 0; kk < j; kk++) {
#pragma HLS PIPELINE II=1
                        sum -= col_panel[i][kk] * diag_tile[kk][j];
                    }
                    col_panel[i][j] = sum / diag_tile[j][j];
                }
            }

            // Write updated column panel back
            store_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    localA[i0 + i][k0 + j] = col_panel[i][j];
                }
            }
        }

        // --- Step 3: Update row panel (tiles to the right of diagonal) ---
        row_panel_loop: for (int tj = tk + 1; tj < NUM_TILES; tj++) {
            int j0 = tj * TILE_SIZE;

            // Load row panel tile
            load_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    row_panel[i][j] = localA[k0 + i][j0 + j];
                }
            }

            // Apply U factor from diagonal tile to row panel:
            // row_panel[i][j] -= sum_kk diag_tile[i][kk] * row_panel[kk][j]  for kk < i
            rpanel_i: for (int i = 0; i < TILE_SIZE; i++) {
                rpanel_j: for (int j = 0; j < TILE_SIZE; j++) {
                    double sum = row_panel[i][j];
                    rpanel_k: for (int kk = 0; kk < i; kk++) {
#pragma HLS PIPELINE II=1
                        sum -= diag_tile[i][kk] * row_panel[kk][j];
                    }
                    row_panel[i][j] = sum;
                }
            }

            // Write updated row panel back
            store_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    localA[k0 + i][j0 + j] = row_panel[i][j];
                }
            }
        }

        // --- Step 4: Update trailing submatrix ---
        // For each block (ti, tj) in trailing submatrix:
        // A[ti][tj] -= col_panel[ti][k] * row_panel[k][tj]
        trail_ti: for (int ti = tk + 1; ti < NUM_TILES; ti++) {
            int i0 = ti * TILE_SIZE;

            // Reload column panel for this row block
            reload_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    col_panel[i][j] = localA[i0 + i][k0 + j];
                }
            }

            trail_tj: for (int tj = tk + 1; tj < NUM_TILES; tj++) {
                int j0 = tj * TILE_SIZE;

                // Load row panel for this column block
                reload_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                        row_panel[i][j] = localA[k0 + i][j0 + j];
                    }
                }

                // Load trailing tile
                load_utile: for (int i = 0; i < TILE_SIZE; i++) {
                    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                        update_tile[i][j] = localA[i0 + i][j0 + j];
                    }
                }

                // Compute rank-TILE_SIZE update: update_tile -= col_panel * row_panel
                update_i: for (int i = 0; i < TILE_SIZE; i++) {
                    update_j: for (int j = 0; j < TILE_SIZE; j++) {
                        double sum = update_tile[i][j];
                        update_k: for (int kk = 0; kk < TILE_SIZE; kk++) {
#pragma HLS PIPELINE II=1
                            sum -= col_panel[i][kk] * row_panel[kk][j];
                        }
                        update_tile[i][j] = sum;
                    }
                }

                // Store updated trailing tile back
                store_utile: for (int i = 0; i < TILE_SIZE; i++) {
                    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                        localA[i0 + i][j0 + j] = update_tile[i][j];
                    }
                }
            }
        }
    }

    // ---- STORE PHASE: write local buffer back to global A ----
    store_i: for (int i = 0; i < N; i++) {
        store_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            A[i][j] = localA[i][j];
        }
    }
}

} // extern "C"
```

**Key tiling changes applied:**

1. **Blocked LU decomposition**: Restructured the flat O(N³) LU into a 4-step tiled algorithm operating on `TILE_SIZE=24` blocks (5×5 tiles for N=120).

2. **Local tile buffers**: Four small tile buffers (`diag_tile`, `col_panel`, `row_panel`, `update_tile`) of size 24×24 = 576 doubles each, which fit in BRAM/registers and are fully partitioned on dim=2 for parallel access.

3. **Separate load/compute/store phases** within each tile step: each tile is explicitly loaded from `localA`, processed locally, then written back.

4. **Reuse**: The column panel tile is reused across all trailing column updates; the row panel is reused across trailing row computations — this is the core reuse benefit of tiling.

Looking at the current code, I need to add pipeline optimizations to the innermost compute loops that don't already have `#pragma HLS PIPELINE II=1`, and add appropriate array partitioning and dependence pragmas to enable effective pipelining.

Key observations:
1. The `diag_lu` loops have inner `kk` loops with `PIPELINE II=1` but the outer loops read/write `diag_tile` with potential dependencies - need `DEPENDENCE inter false` on `diag_tile`
2. The `cpanel` and `rpanel` compute loops have inner `kk` pipelines but outer `i/j` loops are sequential - need to add pipeline to middle loops where possible
3. `localA` is partitioned cyclic factor=8 on dim=2, but tile arrays need full partition on both dims for full parallel access
4. The `rpanel` update has a read-after-write dependency on `row_panel[kk][j]` across `i` iterations which is a real dependency - must not mark false
5. Add `LOOP_TRIPCOUNT` for variable-bound loops (those with `tk+1` to `NUM_TILES`)

```cpp
#include "lu.h"
#include <string.h>

// Tile size for blocked LU decomposition
#define TILE_SIZE 24  // N=120, 120/24=5 tiles exactly

extern "C" {

// Load a tile from global A into local tile buffer
static void load_tile(double A[N][N], double tile[TILE_SIZE][TILE_SIZE],
                      int row_start, int col_start) {
    load_tile_i: for (int i = 0; i < TILE_SIZE; i++) {
        load_tile_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
            int gi = row_start + i;
            int gj = col_start + j;
            tile[i][j] = (gi < N && gj < N) ? A[gi][gj] : 0.0;
        }
    }
}

// Store a tile from local tile buffer back to global A
static void store_tile(double A[N][N], double tile[TILE_SIZE][TILE_SIZE],
                       int row_start, int col_start) {
    store_tile_i: for (int i = 0; i < TILE_SIZE; i++) {
        store_tile_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
            int gi = row_start + i;
            int gj = col_start + j;
            if (gi < N && gj < N)
                A[gi][gj] = tile[i][j];
        }
    }
}

void kernel_lu(
               double A[N + 0][N + 0])
{
#pragma HLS INTERFACE m_axi port=A offset=slave bundle=gmem
#pragma HLS INTERFACE s_axilite port=A bundle=control
#pragma HLS INTERFACE s_axilite port=return bundle=control

    // Full local copy of A for tiled computation
    double localA[N][N];
#pragma HLS ARRAY_PARTITION variable=localA cyclic factor=8 dim=2

    // ---- LOAD PHASE: bring all of A into local buffer ----
    load_i: for (int i = 0; i < N; i++) {
        load_j: for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
            localA[i][j] = A[i][j];
        }
    }

    // ---- COMPUTE PHASE: blocked (tiled) LU decomposition ----
    // Number of tiles along each dimension
    const int NUM_TILES = N / TILE_SIZE;

    // Local tile buffers for the three tile roles in blocked LU
    double diag_tile[TILE_SIZE][TILE_SIZE];    // diagonal (pivot) block
    double col_panel[TILE_SIZE][TILE_SIZE];    // block in pivot column
    double row_panel[TILE_SIZE][TILE_SIZE];    // block in pivot row
    double update_tile[TILE_SIZE][TILE_SIZE];  // trailing submatrix block

#pragma HLS ARRAY_PARTITION variable=diag_tile complete dim=1
#pragma HLS ARRAY_PARTITION variable=diag_tile complete dim=2
#pragma HLS ARRAY_PARTITION variable=col_panel complete dim=1
#pragma HLS ARRAY_PARTITION variable=col_panel complete dim=2
#pragma HLS ARRAY_PARTITION variable=row_panel complete dim=1
#pragma HLS ARRAY_PARTITION variable=row_panel complete dim=2
#pragma HLS ARRAY_PARTITION variable=update_tile complete dim=1
#pragma HLS ARRAY_PARTITION variable=update_tile complete dim=2

    tile_k: for (int tk = 0; tk < NUM_TILES; tk++) {
#pragma HLS LOOP_TRIPCOUNT min=5 max=5
        int k0 = tk * TILE_SIZE;

        // --- Step 1: Load diagonal tile and compute its LU in-place ---
        load_diag: for (int i = 0; i < TILE_SIZE; i++) {
            for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                diag_tile[i][j] = localA[k0 + i][k0 + j];
            }
        }

        // LU factorize the diagonal tile (unblocked)
        diag_lu_i: for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
            // Lower part of diagonal tile
            diag_lu_lower_j: for (int j = 0; j < i; j++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=23
                double sum = diag_tile[i][j];
                diag_lu_lower_k: for (int kk = 0; kk < j; kk++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=23
#pragma HLS DEPENDENCE variable=diag_tile inter false
                    sum -= diag_tile[i][kk] * diag_tile[kk][j];
                }
                diag_tile[i][j] = sum / diag_tile[j][j];
            }
            // Upper part of diagonal tile
            diag_lu_upper_j: for (int j = i; j < TILE_SIZE; j++) {
#pragma HLS LOOP_TRIPCOUNT min=1 max=24
                double sum = diag_tile[i][j];
                diag_lu_upper_k: for (int kk = 0; kk < i; kk++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=23
#pragma HLS DEPENDENCE variable=diag_tile inter false
                    sum -= diag_tile[i][kk] * diag_tile[kk][j];
                }
                diag_tile[i][j] = sum;
            }
        }

        // Write factorized diagonal tile back to localA
        store_diag: for (int i = 0; i < TILE_SIZE; i++) {
            for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                localA[k0 + i][k0 + j] = diag_tile[i][j];
            }
        }

        // --- Step 2: Update column panel (tiles below diagonal) ---
        col_panel_loop: for (int ti = tk + 1; ti < NUM_TILES; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=4
            int i0 = ti * TILE_SIZE;

            // Load this column panel tile
            load_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    col_panel[i][j] = localA[i0 + i][k0 + j];
                }
            }

            // Apply L factor from diagonal tile to column panel:
            // col_panel[i][j] -= sum_kk col_panel[i][kk] * diag_tile[kk][j]  for kk < j
            // then col_panel[i][j] /= diag_tile[j][j]
            cpanel_i: for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                cpanel_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                    double sum = col_panel[i][j];
                    cpanel_k: for (int kk = 0; kk < j; kk++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=23
#pragma HLS DEPENDENCE variable=col_panel inter false
                        sum -= col_panel[i][kk] * diag_tile[kk][j];
                    }
                    col_panel[i][j] = sum / diag_tile[j][j];
                }
            }

            // Write updated column panel back
            store_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    localA[i0 + i][k0 + j] = col_panel[i][j];
                }
            }
        }

        // --- Step 3: Update row panel (tiles to the right of diagonal) ---
        row_panel_loop: for (int tj = tk + 1; tj < NUM_TILES; tj++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=4
            int j0 = tj * TILE_SIZE;

            // Load row panel tile
            load_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    row_panel[i][j] = localA[k0 + i][j0 + j];
                }
            }

            // Apply U factor from diagonal tile to row panel:
            // row_panel[i][j] -= sum_kk diag_tile[i][kk] * row_panel[kk][j]  for kk < i
            rpanel_i: for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                rpanel_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                    double sum = row_panel[i][j];
                    rpanel_k: for (int kk = 0; kk < i; kk++) {
#pragma HLS PIPELINE II=1
#pragma HLS LOOP_TRIPCOUNT min=0 max=23
#pragma HLS DEPENDENCE variable=row_panel inter false
                        sum -= diag_tile[i][kk] * row_panel[kk][j];
                    }
                    row_panel[i][j] = sum;
                }
            }

            // Write updated row panel back
            store_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    localA[k0 + i][j0 + j] = row_panel[i][j];
                }
            }
        }

        // --- Step 4: Update trailing submatrix ---
        // For each block (ti, tj) in trailing submatrix:
        // A[ti][tj] -= col_panel[ti][k] * row_panel[k][tj]
        trail_ti: for (int ti = tk + 1; ti < NUM_TILES; ti++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=4
            int i0 = ti * TILE_SIZE;

            // Reload column panel for this row block
            reload_cpanel: for (int i = 0; i < TILE_SIZE; i++) {
                for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                    col_panel[i][j] = localA[i0 + i][k0 + j];
                }
            }

            trail_tj: for (int tj = tk + 1; tj < NUM_TILES; tj++) {
#pragma HLS LOOP_TRIPCOUNT min=0 max=4
                int j0 = tj * TILE_SIZE;

                // Load row panel for this column block
                reload_rpanel: for (int i = 0; i < TILE_SIZE; i++) {
                    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                        row_panel[i][j] = localA[k0 + i][j0 + j];
                    }
                }

                // Load trailing tile
                load_utile: for (int i = 0; i < TILE_SIZE; i++) {
                    for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS PIPELINE II=1
                        update_tile[i][j] = localA[i0 + i][j0 + j];
                    }
                }

                // Compute rank-TILE_SIZE update: update_tile -= col_panel * row_panel
                update_i: for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                    update_j: for (int j = 0; j < TILE_SIZE; j++) {
#pragma HLS LOOP_TRIPCOUNT min=24 max=24
                        double sum = update_tile[i][j];
